package com.matejpcs.netflared;
import com.google.gson.*;import java.io.*;import java.net.*;import java.net.http.*;import java.nio.charset.StandardCharsets;import java.time.Duration;import java.util.*;
public final class CloudflareClient{private static final String API="https://api.cloudflare.com/client/v4";private final String token;private final HttpClient http=HttpClient.newBuilder().connectTimeout(Duration.ofSeconds(15)).build();public CloudflareClient(String t){token=t;}public record Zone(String id,String name,String accountId,String accountName){}public record Tunnel(String id,String name){}public void verify()throws IOException,InterruptedException{req("GET","/user/tokens/verify",null,200);}public List<Zone> listZones()throws IOException,InterruptedException{JsonObject r=req("GET","/zones?per_page=100",null,200);List<Zone>z=new ArrayList<>();for(JsonElement e:r.getAsJsonArray("result")){JsonObject x=e.getAsJsonObject(),a=x.has("account")?x.getAsJsonObject("account"):null;z.add(new Zone(x.get("id").getAsString(),x.get("name").getAsString(),a!=null&&a.has("id")?a.get("id").getAsString():"",a!=null&&a.has("name")?a.get("name").getAsString():""));}return z;}public Tunnel createTunnel(String a,String n)throws IOException,InterruptedException{JsonObject b=new JsonObject();b.addProperty("name",n);b.addProperty("config_src","cloudflare");JsonObject r=req("POST","/accounts/"+a+"/cfd_tunnel",b,200).getAsJsonObject("result");return new Tunnel(r.get("id").getAsString(),r.get("name").getAsString());}public String getTunnelToken(String a,String id)throws IOException,InterruptedException{return req("GET","/accounts/"+a+"/cfd_tunnel/"+id+"/token",null,200).get("result").getAsString();}public void updateConfiguration(String a,String id,String h,int p)throws IOException,InterruptedException{JsonArray i=new JsonArray();JsonObject r=new JsonObject();r.addProperty("hostname",h);r.addProperty("service","tcp://localhost:"+p);i.add(r);JsonObject f=new JsonObject();f.addProperty("service","http_status:404");i.add(f);JsonObject c=new JsonObject();c.add("ingress",i);JsonObject b=new JsonObject();b.add("config",c);req("PUT","/accounts/"+a+"/cfd_tunnel/"+id+"/configurations",b,200);}public void upsertDns(String z,String h,String target)throws IOException,InterruptedException{String q=URLEncoder.encode(h,StandardCharsets.UTF_8);JsonArray a=req("GET","/zones/"+z+"/dns_records?type=CNAME&name="+q+"&per_page=100",null,200).getAsJsonArray("result");String id=a.isEmpty()?null:a.get(0).getAsJsonObject().get("id").getAsString();JsonObject b=new JsonObject();b.addProperty("type","CNAME");b.addProperty("name",h);b.addProperty("content",target);b.addProperty("ttl",1);b.addProperty("proxied",true);req(id==null?"POST":"PUT",id==null?"/zones/"+z+"/dns_records":"/zones/"+z+"/dns_records/"+id,b,200);}private JsonObject req(String m,String p,JsonObject body,int e)throws IOException,InterruptedException{HttpRequest.Builder b=HttpRequest.newBuilder(URI.create(API+p)).timeout(Duration.ofSeconds(30)).header("Authorization","Bearer "+token).header("Accept","application/json");if(body!=null)b.header("Content-Type","application/json").method(m,HttpRequest.BodyPublishers.ofString(body.toString()));else b.method(m,HttpRequest.BodyPublishers.noBody());HttpResponse<String>r=http.send(b.build(),HttpResponse.BodyHandlers.ofString());JsonObject j=JsonParser.parseString(r.body()).getAsJsonObject();if(r.statusCode()!=e||!j.has("success")||!j.get("success").getAsBoolean())throw new IOException("Cloudflare API request failed (HTTP "+r.statusCode()+")");return j;}}
